// 🔹 base
const input = $input.first().json;
const body = input.body || {};
const data = body.data || {};
const msg = data.message || {};
const key = data.key || {};
const server_url = body.server_url || {};

// 📱 número
const raw = input.numero || key.remoteJid || "";
const numero = raw.split('@')[0].replace(/\D/g, '');

// 🧠 detectar tipo de mensaje (SIN sobreescribir)
let messageType = "unknown";
if (msg.conversation) messageType = "texto";
else if (msg.extendedTextMessage) messageType = "texto";
else if (msg.audioMessage) messageType = "audio";
else if (msg.imageMessage) messageType = "imagen";

// 💬 contenido (prioridad correcta)
let content = "";
if (msg.conversation) content = msg.conversation;
else if (msg.extendedTextMessage) content = msg.extendedTextMessage.text;
else if (msg.imageMessage){
  content = msg.imageMessage.caption;
}

// 🆔 IDs
const messageID = key.id || "";
const chatID = body.sender || raw;
// ❌ ignorar grupos
if (chatID.endsWith('@g.us')) {
  messageType = "grupo";
  return [{}];
}

// 🟢🔵 instancia
const instanceName = body.instance || "";

// 🔐 APIKEY dinámica
const apikeys = {
  "bot-pagos": "68E6084D0489-44B9-909A-632E54ACDD64",
  "default": "040E38A519FF-405D-9860-D083DFE9754F"
};

const apikey = apikeys[instanceName] || apikeys["default"];

// 👨‍💼 empleados
const empleados = [
  "593961778319",
  "593996464991",
  "593961412826",
  "593961702129",
  "593986740052",
];

const esEmpleado = empleados.includes(numero);
const tipo = esEmpleado ? "empleado" : "cliente";

let color="azul";
if (instanceName == "bot-pagos") {
  color="verde";
}
// 🚀 OUTPUT ORDENADO
return [
  {
    json: {
      content,
      instance: {
        name: instanceName,
        apikey,
        server_url,
        color,
      },
      message: {
        id: messageID,
        chat_id: chatID,
        from: numero,
        type: messageType,
        content,
      },
      contact: {
        numero,
        tipo,
        esEmpleado
      }
    }
  }
];

// ============================================
// NODO CODE - VERSIÓN PARA LARAVEL LOCAL
// ============================================
// 1. Obtener datos del nodo "Normalizar"
const datos = $input.item.json;

// 2. DEBUG: Ver qué tenemos
console.log("📱 Datos de Normalizar recibidos:");
console.log("- Teléfono:", datos.contact?.numero);
console.log("- Instancia:", datos.instance?.name);
console.log("- Color:", datos.instance?.color);
console.log("- Mensaje:", datos.message?.content);

// 3. Si no hay teléfono, salir
if (!datos.contact?.numero) {
  console.log("❌ No hay teléfono, saliendo");
  return [];
}

// 4. Configuración para Laravel LOCAL
const URL = "http://localhost:8000/api/chat/n8n/webhook";  // ← CAMBIADO
const TOKEN = "laravel_token_123";  // ← CAMBIADO

// 5. Preparar payload para Laravel (formato más simple)
const payload = {
  telefono: datos.contact.numero,
  mensaje: datos.message?.content || "",
  tipo: datos.message?.type || "texto",
  instance: datos.instance?.name || "Streamify Azul",
  color: datos.instance?.color || "azul",
  es_empleado: datos.contact?.esEmpleado || false,

  // Campos opcionales que tu Laravel puede manejar
  nombre: datos.contact?.tipo === 'empleado' ? 'Empleado' : 'Cliente',
  external_message_id: datos.message?.id || `n8n_${Date.now()}`,
  canal_user_id: datos.message?.chat_id || `${datos.contact.numero}@s.whatsapp.net`
};

// 6. DEBUG: Ver payload
console.log("📦 Payload a enviar a Laravel:");
console.log(JSON.stringify(payload, null, 2));

// 7. ENVIAR a Laravel usando $http
try {
  console.log(`🚀 Enviando a Laravel local: ${URL}`);

  const response = await $http.post(URL, {
    headers: {
      'X-N8N-Token': TOKEN,  // ← CAMBIADO (header correcto)
      'Content-Type': 'application/json'
    },
    body: payload
  });

  console.log(`✅ Éxito! Status: ${response.status}`);
  console.log("Respuesta de Laravel:", response.body);

} catch (error) {
  console.log(`❌ Error al enviar a Laravel: ${error.message}`);
  console.log("Error completo:", error);
}

// 8. Este nodo es terminal
return [];
